import {clone,bondId} from './chem-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fitGraph(g,w=720,h=350){const out=clone(g);if(!out.atoms.length)return out;const xs=out.atoms.map(a=>a.x),ys=out.atoms.map(a=>a.y),loX=Math.min(...xs),loY=Math.min(...ys),dx=Math.max(...xs)-loX,dy=Math.max(...ys)-loY,s=Math.min((w-140)/Math.max(dx,140),(h-105)/Math.max(dy,95),1.9);for(const a of out.atoms){a.x=(a.x-loX)*s+(w-dx*s)/2;a.y=(a.y-loY)*s+(h-dy*s)/2}return out}
function implicit(g,a){if(a.label)return a.label;if(a.el==='H'||!['C','N','O'].includes(a.el))return a.el;const used=g.bonds.filter(b=>b.a===a.id||b.b===a.id).reduce((s,b)=>s+b.order,0),val=a.el==='C'?4:a.el==='N'?((a.charge||0)>0?4:3):((a.charge||0)>0?3:(a.charge||0)<0?1:2),hs=Math.max(0,val-used);return a.el+(hs?'H'+(hs===1?'':hs):'')}
function colour(el){return ({O:'#b04b42',N:'#426a9d',Cl:'#447a45',Br:'#9c6152',H:'#6c8077',C:'#263e36',Mg:'#598d62'})[el]||'#425f52'}
export function drawGraph(g,{labels=false,interactive=false,width=720,height=350}={}){const drawn=fitGraph(g,width,height),atomMap=new Map(drawn.atoms.map(a=>[a.id,a]));let out='';for(const b of drawn.bonds){const a=atomMap.get(b.a),c=atomMap.get(b.b);if(!a||!c)continue;const dx=c.x-a.x,dy=c.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,offset=b.order===1?[0]:b.order===2?[-3,3]:[-5,0,5];for(const off of offset)out+=`<line x1="${a.x+ux*17-uy*off}" y1="${a.y+uy*17+ux*off}" x2="${c.x-ux*17-uy*off}" y2="${c.y-uy*17+ux*off}" class="chem-bond"/>`;if(interactive)out+=`<g class="bond-anchor" data-anchor="bond:${esc(bondId(b.a,b.b))}" role="button" tabindex="0" aria-label="Bond ${esc(b.a)} to ${esc(b.b)}"><circle cx="${(a.x+c.x)/2}" cy="${(a.y+c.y)/2}" r="16" class="anchor-hit"/><circle cx="${(a.x+c.x)/2}" cy="${(a.y+c.y)/2}" r="4" class="anchor-dot"/></g>`}for(const a of drawn.atoms){const q=a.charge||0,charge=q?((Math.abs(q)>1?Math.abs(q):'')+(q>0?'+':'−')):'';out+=`<g class="chem-atom ${interactive?'atom-anchor':''}" ${interactive?`data-anchor="atom:${esc(a.id)}" role="button" tabindex="0" aria-label="Atom ${esc(a.id)} ${esc(a.el)}${q?' charge '+q:''}"`:''}><circle cx="${a.x}" cy="${a.y}" r="21" class="atom-halo"/><text x="${a.x}" y="${a.y+7}" text-anchor="middle" fill="${colour(a.el)}" class="chem-symbol">${esc(implicit(drawn,a))}</text>${charge?`<text x="${a.x+21}" y="${a.y-9}" class="chem-charge" fill="${colour(a.el)}">${charge}</text>`:''}${labels?`<text x="${a.x}" y="${a.y+30}" text-anchor="middle" class="atom-label">${esc(a.id)}</text>`:''}</g>`}return {markup:out,graph:drawn}}
export function moleculeSVG(g,{labels=false,caption='',className=''}={}){const draw=drawGraph(g,{labels});return `<svg class="molecule-svg ${className}" viewBox="0 0 720 350" role="img" aria-label="${esc(caption||'Molecular structure')}">${caption?`<title>${esc(caption)}</title>`:''}${draw.markup}</svg>`}
function anchors(g){const out=new Map(g.atoms.map(a=>['atom:'+a.id,{x:a.x,y:a.y}]));for(const b of g.bonds){const a=g.atoms.find(x=>x.id===b.a),c=g.atoms.find(x=>x.id===b.b);out.set('bond:'+bondId(b.a,b.b),{x:(a.x+c.x)/2,y:(a.y+c.y)/2})}return out}
function curve(a,b,bend=55){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,start={x:a.x+ux*13,y:a.y+uy*13},end={x:b.x-ux*17,y:b.y-uy*17},cx=(start.x+end.x)/2-uy*bend,cy=(start.y+end.y)/2+ux*bend;return `M ${start.x} ${start.y} Q ${cx} ${cy} ${end.x} ${end.y}`}
export class ElectronCanvas{
 constructor(container,graph,arrows,onChange){this.container=container;this.source=graph;this.arrows=clone(arrows||[]);this.onChange=onChange;this.history=[];this.future=[];this.start=null;this.selected=-1;this.render()}
 render(){const draw=drawGraph(this.source,{labels:true,interactive:true});this.points=anchors(draw.graph);this.container.innerHTML=`<svg class="electron-svg" viewBox="0 0 720 350" aria-label="Electron-pushing canvas. Drag or click between atom and bond anchors."><defs><marker id="electron-head" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M1 1 L9 5 L1 9" fill="none" stroke="#ab612b" stroke-width="1.8"/></marker></defs><g class="source-structure">${draw.markup}</g><g class="electron-arrows">${this.arrows.map((a,i)=>{const from=this.points.get(a.from),to=this.points.get(a.to);return from&&to?`<path d="${curve(from,to,a.bend??55)}" class="electron-arrow ${i===this.selected?'selected':''}" marker-end="url(#electron-head)" data-arrow="${i}" role="button" tabindex="0" aria-label="Electron arrow ${i+1}: ${esc(a.from)} to ${esc(a.to)}"/>`:''}).join('')}</g><path class="pending-arrow" marker-end="url(#electron-head)"/><circle class="start-indicator" r="23" fill="none" stroke="#b7854f" stroke-dasharray="3 4" visibility="hidden"/></svg>`;this.svg=this.container.querySelector('svg');this.svg.addEventListener('pointerdown',e=>this.down(e));this.svg.addEventListener('pointermove',e=>this.move(e));this.svg.addEventListener('pointerup',e=>this.up(e));this.svg.addEventListener('pointercancel',()=>this.cancel());this.svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const key=e.target.closest('[data-anchor]')?.dataset.anchor;if(key){e.preventDefault();this.clickAnchor(key)}}if(e.key==='Escape')this.cancel();if(e.key==='Delete'&&this.selected>=0)this.remove()});if(this.start){const p=this.points.get(this.start),mark=this.svg.querySelector('.start-indicator');mark.setAttribute('cx',p.x);mark.setAttribute('cy',p.y);mark.setAttribute('visibility','visible')}}
 point(e){const p=this.svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(this.svg.getScreenCTM().inverse())}
 nearest(point){let best=null,d=30;for(const [key,p]of this.points){const n=Math.hypot(point.x-p.x,point.y-p.y);if(n<d){d=n;best=key}}return best}
 down(e){const arrow=e.target.closest('[data-arrow]');if(arrow){this.selected=+arrow.dataset.arrow;this.start=null;this.render();return}const anchor=e.target.closest('[data-anchor]')?.dataset.anchor;if(!anchor)return;e.preventDefault();this.drag={key:anchor,point:this.point(e),moved:false,pointer:e.pointerId};this.svg.setPointerCapture(e.pointerId)}
 move(e){if(!this.drag)return;const p=this.point(e);if(Math.hypot(p.x-this.drag.point.x,p.y-this.drag.point.y)>5)this.drag.moved=true;const to=this.nearest(p),target=to?this.points.get(to):p;this.svg.querySelector('.pending-arrow').setAttribute('d',curve(this.points.get(this.drag.key),target,e.shiftKey?-55:55))}
 up(e){if(!this.drag)return;const drag=this.drag;this.drag=null;const target=this.nearest(this.point(e));if(drag.moved){if(target&&target!==drag.key)this.add(drag.key,target,e.shiftKey?-55:55);else this.render()}else this.clickAnchor(drag.key)}
 clickAnchor(key){if(!this.start){this.start=key;this.render()}else if(this.start===key){this.start=null;this.render()}else{const from=this.start;this.start=null;this.add(from,key)}}
 cancel(){this.drag=null;this.start=null;this.render()}
 checkpoint(){this.history.push(clone(this.arrows));this.history=this.history.slice(-40);this.future=[]}
 add(from,to,bend=55){this.checkpoint();this.arrows.push({from,to,bend});this.selected=this.arrows.length-1;this.start=null;this.render();this.changed()}
 remove(){if(this.selected<0)return;this.checkpoint();this.arrows.splice(this.selected,1);this.selected=-1;this.render();this.changed()}
 flip(){if(this.selected<0)return;this.checkpoint();this.arrows[this.selected].bend=-(this.arrows[this.selected].bend??55);this.render();this.changed()}
 clear(){if(!this.arrows.length)return;this.checkpoint();this.arrows=[];this.selected=-1;this.start=null;this.render();this.changed()}
 undo(){if(!this.history.length)return;this.future.push(clone(this.arrows));this.arrows=this.history.pop();this.selected=-1;this.start=null;this.render();this.changed()}
 redo(){if(!this.future.length)return;this.history.push(clone(this.arrows));this.arrows=this.future.pop();this.selected=-1;this.start=null;this.render();this.changed()}
 changed(){this.onChange?.(clone(this.arrows))}
 destroy(){this.container.innerHTML=''}
}
